  // ============ Merge ============
  public static Query.QueryValue.Builder mergeQueryValue(
      Query.QueryValue dst, Query.QueryValue src) {
    Query.QueryValue.Builder builder = dst.toBuilder();
    if (dst.getValueCase() == Query.QueryValue.ValueCase.VALUE_NOT_SET) {
      switch (src.getValueCase()) {
        case STRING_VALUE:
          builder.setStringValue(src.getStringValue());
          break;
        case INT_VALUE:
          builder.setIntValue(src.getIntValue());
          break;
        case DOUBLE_VALUE:
          builder.setDoubleValue(src.getDoubleValue());
          break;
        case BOOL_VALUE:
          builder.setBoolValue(src.getBoolValue());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Query.Predicate.Builder mergePredicate(Query.Predicate dst, Query.Predicate src) {
    Query.Predicate.Builder builder = dst.toBuilder();
    if (dst.getFieldName().isEmpty()) {
      builder.setFieldName(src.getFieldName());
    }
    if (dst.getOpValue() == 0) {
      builder.setOpValue(src.getOpValue());
    }
    if (!dst.hasValue() && src.hasValue()) {
      builder.setValue(src.getValue());
    } else if (dst.hasValue() && src.hasValue()) {
      builder.setValue(mergeQueryValue(dst.getValue(), src.getValue()).build());
    }
    if (dst.getValuesList().isEmpty()) {
      builder.addAllValues(src.getValuesList());
    }
    return builder;
  }

  public static Query.PredicateGroup.Builder mergePredicateGroup(
      Query.PredicateGroup dst, Query.PredicateGroup src) {
    Query.PredicateGroup.Builder builder = dst.toBuilder();
    if (dst.getOpValue() == 0) {
      builder.setOpValue(src.getOpValue());
    }
    if (dst.getPredicatesList().isEmpty()) {
      builder.addAllPredicates(src.getPredicatesList());
    }
    if (dst.getGroupsList().isEmpty()) {
      builder.addAllGroups(src.getGroupsList());
    }
    return builder;
  }

  public static Query.SortField.Builder mergeSortField(Query.SortField dst, Query.SortField src) {
    Query.SortField.Builder builder = dst.toBuilder();
    if (dst.getFieldName().isEmpty()) {
      builder.setFieldName(src.getFieldName());
    }
    if (dst.getDirectionValue() == 0) {
      builder.setDirectionValue(src.getDirectionValue());
    }
    return builder;
  }

  public static Query.CollectionQuery.Builder mergeCollectionQuery(
      Query.CollectionQuery dst, Query.CollectionQuery src) {
    Query.CollectionQuery.Builder builder = dst.toBuilder();
    if (!dst.hasWhere() && src.hasWhere()) {
      builder.setWhere(src.getWhere());
    } else if (dst.hasWhere() && src.hasWhere()) {
      builder.setWhere(mergePredicateGroup(dst.getWhere(), src.getWhere()).build());
    }
    if (dst.getOrderByList().isEmpty()) {
      builder.addAllOrderBy(src.getOrderByList());
    }
    if (dst.getLimit() == 0) {
      builder.setLimit(src.getLimit());
    }
    if (dst.getOffset() == 0) {
      builder.setOffset(src.getOffset());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> queryValueToEnvVar(Query.QueryValue msg) {
    Map<String, String> result = new HashMap<>();
    return result;
  }

  public static Query.QueryValue.Builder queryValueFromEnvVar(Map<String, String> env) {
    Query.QueryValue.Builder builder = Query.QueryValue.newBuilder();
    return builder;
  }

  public static Map<String, String> predicateToEnvVar(Query.Predicate msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_PREDICATE_FIELD_NAME", msg.getFieldName());
    result.put("PROTO_PREDICATE_OP", comparisonOpToString(msg.getOp()));
    if (msg.hasValue()) {
      result.putAll(queryValueToEnvVar(msg.getValue()));
    }
    return result;
  }

  public static Query.Predicate.Builder predicateFromEnvVar(Map<String, String> env) {
    Query.Predicate.Builder builder = Query.Predicate.newBuilder();
    String val;
    val = env.get("PROTO_PREDICATE_FIELD_NAME");
    if (val != null && !val.isEmpty()) {
      builder.setFieldName(val);
    }
    val = env.get("PROTO_PREDICATE_OP");
    if (val != null && !val.isEmpty()) {
      builder.setOp(parseComparisonOp(val));
    }
    {
      var sub = queryValueFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setValue(sub);
      }
    }
    return builder;
  }

  public static Map<String, String> predicateGroupToEnvVar(Query.PredicateGroup msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_PREDICATE_GROUP_OP", logicalOpToString(msg.getOp()));
    return result;
  }

  public static Query.PredicateGroup.Builder predicateGroupFromEnvVar(Map<String, String> env) {
    Query.PredicateGroup.Builder builder = Query.PredicateGroup.newBuilder();
    String val;
    val = env.get("PROTO_PREDICATE_GROUP_OP");
    if (val != null && !val.isEmpty()) {
      builder.setOp(parseLogicalOp(val));
    }
    return builder;
  }

  public static Map<String, String> sortFieldToEnvVar(Query.SortField msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_SORT_FIELD_FIELD_NAME", msg.getFieldName());
    result.put("PROTO_SORT_FIELD_DIRECTION", sortDirectionToString(msg.getDirection()));
    return result;
  }

  public static Query.SortField.Builder sortFieldFromEnvVar(Map<String, String> env) {
    Query.SortField.Builder builder = Query.SortField.newBuilder();
    String val;
    val = env.get("PROTO_SORT_FIELD_FIELD_NAME");
    if (val != null && !val.isEmpty()) {
      builder.setFieldName(val);
    }
    val = env.get("PROTO_SORT_FIELD_DIRECTION");
    if (val != null && !val.isEmpty()) {
      builder.setDirection(parseSortDirection(val));
    }
    return builder;
  }

  public static Map<String, String> collectionQueryToEnvVar(Query.CollectionQuery msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasWhere()) {
      result.putAll(predicateGroupToEnvVar(msg.getWhere()));
    }
    result.put("PROTO_COLLECTION_QUERY_LIMIT", String.valueOf(msg.getLimit()));
    result.put("PROTO_COLLECTION_QUERY_OFFSET", String.valueOf(msg.getOffset()));
    return result;
  }

  public static Query.CollectionQuery.Builder collectionQueryFromEnvVar(Map<String, String> env) {
    Query.CollectionQuery.Builder builder = Query.CollectionQuery.newBuilder();
    String val;
    {
      var sub = predicateGroupFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setWhere(sub);
      }
    }
    val = env.get("PROTO_COLLECTION_QUERY_LIMIT");
    if (val != null && !val.isEmpty()) {
      builder.setLimit(Integer.parseInt(val));
    }
    val = env.get("PROTO_COLLECTION_QUERY_OFFSET");
    if (val != null && !val.isEmpty()) {
      builder.setOffset(Integer.parseInt(val));
    }
    return builder;
  }
